#[derive(Deserialize)]
struct LegacyOrder {
    order_id: String,
    #[serde(deserialize_with = "de_sku")]   // trim + uppercase at the boundary
    sku: String,
    qty: u32,
}

impl From<LegacyOrder> for Order {          // structural translation, serde not involved
    fn from(l: LegacyOrder) -> Self { Self { id: l.order_id, sku: l.sku, quantity: l.qty } }
}

impl TryFrom<LegacyOrder> for Order {
    type Error = InvalidMessage;
    fn try_from(l: LegacyOrder) -> Result<Self, Self::Error> {
        if l.qty == 0 { return Err(InvalidMessage::MissingQty); }
        Ok(Order { id: l.order_id, sku: l.sku.to_uppercase(), quantity: l.qty })
    }
}
